namespace Riverbend {
    public partial class DemoGame {
        int commandPartner;
        void CompanionCommandsUI(){
            RectFill(new Rect(285,80,1030,750),new Color(.025f,.065f,.06f,.98f));Label(335,110,850,50,L("伙伴命令 · 世界暂停","Companion commands · world paused"),heading);
            var partners=save.partners.Where(p=>p.active).ToArray();if(partners.Length==0){Label(335,210,870,100,L("当前没有出勤伙伴，在公司整备安排出勤。","No assigned companion. Assign one at the depot."));if(Button(335,735,870,40,L("返回","Back")))Close();return;}
            commandPartner=Mathf.Clamp(commandPartner,0,partners.Length-1);var p=partners[commandPartner];for(int i=0;i<partners.Length;i++)if(Button(335+i*440,200,425,45,(partners[i].type=="H01"?L("作业猫","Work cat"):L("作业犬","Work dog"))+" #"+(i+1)))commandPartner=i;
            string[] commands={"Work","Station","Point","Quiet","Wait","Truck"};string[] zh={"跟随作业","在当前位置定点作业","前往瞄准地点作业","安静跟随","原地等待（保留按住目标）","回车（释放未交接目标）"};string[] en={"Follow and work","Work at current position","Work at aimed location","Quiet follow","Wait (retain held target)","Return to truck (release target)"};
            for(int i=0;i<commands.Length;i++)if(Button(335,270+i*64,870,50,L(zh[i],en[i]))){var actor=world.dynamicRoot.GetComponentsInChildren<DemoPartner>().FirstOrDefault(a=>a.record.id==p.id);Vector3 point=actor?actor.transform.position:world.controller.transform.position;
                if(commands[i]=="Point"){if(!Physics.Raycast(world.cam.transform.position,world.cam.transform.forward,out var hit,40,1<<9)||hit.normal.y<.9f){Notify(L("请瞄准40米内的可行走地面","Aim at walkable ground within 40m"));continue;}point=world.AdditionalGroundNode(hit.point);if(world.Route(actor?actor.transform.position:world.controller.transform.position,point).Count==0){Notify(L("伙伴无法到达该位置","Companion cannot reach that point"));continue;}}
                if(commands[i]!="Wait"&&!string.IsNullOrEmpty(p.target)){var animal=save.job.animals.FirstOrDefault(a=>a.id==p.target);if(animal!=null&&animal.partnerClaim==p.id){animal.partnerClaim=null;animal.partnerHeld=false;}p.target=null;}
                p.command=commands[i];p.commandPoint=point;Persist();Close();return;}
            if(Button(335,735,870,40,L("返回 · T关闭","Back · T closes")))Close();
        }
        void PartnersUI(){
            Label(335,185,880,45,L("伙伴整备 · 出勤 ","Companions · assigned ")+save.partners.Count(p=>p.active)+"/"+(SkillValue("partnerRestCooldownMultiplier",1)<=.4f?2:1),heading);
            for(int i=0;i<config.content.companions.Length;i++){var d=config.content.companions[i];if(Button(335,245+i*65,870,50,L("购买 ","Buy ")+L(d.zh,d.en)+" ¥"+d.price+" · Lv"+d.unlockLevel,save.cash>=d.price&&PlayerLevel>=d.unlockLevel&&save.partners.Count(p=>p.type==d.id)<d.maximumOwned)){save.cash-=d.price;save.partners.Add(new PartnerRecord{id=Guid.NewGuid().ToString("N"),type=d.id});Persist();}}
            for(int i=0;i<save.partners.Count;i++){var p=save.partners[i];float y=420+i*58;Label(335,y,400,45,(p.type=="H01"?L("作业猫","Work cat"):L("作业犬","Work dog"))+" #"+(i+1),heading);
                if(Button(710,y,230,43,p.active?L("取消出勤","Unassign"):L("安排出勤","Assign"))){int limit=SkillValue("partnerRestCooldownMultiplier",1)<=.4f?2:1;if(p.active||save.partners.Count(p=>p.active)<limit){p.active=!p.active;Persist();}else Notify(L("出勤席位不足","No free companion assignment"));}
                if(p.type=="H01"&&Button(955,y,255,43,p.lethal?L("模式：击杀","Mode: lethal"):L("模式：活捉","Mode: live"))){p.lethal=!p.lethal;Persist();}}
            if(Button(335,732,875,35,L("返回技能","Back to skills")))panel="growth";
        }
        public void TransferPartner(DemoPartner partner){
            var j=save.job;var a=j.animals.FirstOrDefault(a=>a.id==partner.record.target);if(a==null||a.dead||!a.partnerHeld||a.partnerClaim!=partner.record.id)return;
            int slot=Enumerable.Range(0,j.kit.Count).Where(i=>(IsCage((Kit)j.kit[i])||j.kit[i]==(int)Kit.Net)&&string.IsNullOrEmpty(j.cargoIds[i])).DefaultIfEmpty(-1).First();
            if(slot<0||!CanOccupySlot(slot)){Notify(L("携带空小笼或网袋，并留出占用后的空间","Carry an empty cage or net with space after occupation"));return;}
            a.partnerClaim=null;a.partnerHeld=false;a.contained=true;a.controlMethod="Companion";a.deviceId=null;j.cargoIds[slot]=a.id;partner.record.target=null;partner.record.rest=4*SkillValue("partnerRestCooldownMultiplier",1);
            if(world.animals.TryGetValue(a.id,out var actor)){world.animals.Remove(a.id);Destroy(actor.gameObject);}Select(slot);Persist();
        }
    }
    public partial class DemoWorld {
        void RestorePartners(){foreach(var a in game.save.job.animals.Where(a=>!string.IsNullOrEmpty(a.partnerClaim)))if(!game.save.partners.Any(p=>p.active&&p.id==a.partnerClaim&&p.target==a.id)){a.partnerClaim=null;a.partnerHeld=false;}foreach(var p in game.save.partners.Where(p=>p.active)){var target=game.save.job.animals.FirstOrDefault(a=>a.id==p.target&&!a.dead&&!a.contained&&!a.terminal);if(target==null){p.target=null;}var root=new GameObject(p.type=="H01"?"Work cat":"Work dog");root.transform.SetParent(dynamicRoot);root.transform.position=target!=null&&target.partnerHeld?target.position-Vector3.forward*.35f:p.position!=Vector3.zero?p.position:controller.transform.position+Vector3.right*(p.type=="H01"?1:-1);var actor=root.AddComponent<DemoPartner>();actor.world=this;actor.record=p;actor.Build();}}
    }
    public class DemoPartner:MonoBehaviour {
        public DemoWorld world;public PartnerRecord record;List<Vector3> route=new List<Vector3>();int node;float think;DemoCatalog.Companion Definition=>world.game.config.content.companions.First(d=>d.id==record.type);
        public void Build(){float s=record.type=="H01"?.5f:.8f;world.Shape("Partner body",PrimitiveType.Sphere,new Vector3(0,s*.55f,0),new Vector3(s*.5f,s*.6f,s),world.cream,transform);world.Shape("Partner head",PrimitiveType.Sphere,new Vector3(0,s*.8f,s*.5f),Vector3.one*s*.45f,world.fur,transform);foreach(float x in new[]{-.17f,.17f}){world.Shape("Partner ear",PrimitiveType.Capsule,new Vector3(x,s,s*.5f),new Vector3(.1f,.18f,.1f),world.fur,transform);foreach(float z in new[]{-.25f,.3f})world.Shape("Partner leg",PrimitiveType.Capsule,new Vector3(x,s*.2f,z),new Vector3(.09f,s*.3f,.09f),world.fur,transform);}world.Box("Collar",new Vector3(0,s*.65f,s*.3f),new Vector3(s*.52f,.08f,.08f),world.teal,transform,false);gameObject.layer=8;var c=gameObject.AddComponent<BoxCollider>();c.isTrigger=true;c.center=Vector3.up*.4f;c.size=new Vector3(.4f,.8f,.8f);gameObject.AddComponent<DemoTarget>().kind="partner";}
        void Walk(Vector3 goal,float dt){think-=dt;if(think<=0){route=world.Route(transform.position,goal);node=route.Count>1?1:0;think=.6f;}if(node<route.Count){Vector3 delta=route[node]-transform.position;Vector3 flat=new Vector3(delta.x,0,delta.z);if(flat.sqrMagnitude>.002f)transform.rotation=Quaternion.Slerp(transform.rotation,Quaternion.LookRotation(flat),dt*8);transform.position=Vector3.MoveTowards(transform.position,route[node],3*dt);if(Vector3.Distance(transform.position,route[node])<.1f)node++;}}
        void Update(){var g=world.game;if(g.Paused||g.save.atDepot)return;float dt=Time.deltaTime;record.rest=Mathf.Max(0,record.rest-dt);var d=Definition;DemoAnimal target=null;if(record.target!=null)world.animals.TryGetValue(record.target,out target);
            if(target&&(target.record.dead||target.record.contained||target.record.terminal)){target.record.partnerClaim=null;target.record.partnerHeld=false;target=null;record.target=null;}
            if(record.command=="Truck"||record.command=="Quiet"||record.command=="Wait"){if(record.command!="Wait")Walk(record.command=="Truck"?DemoWorld.VanPoint+new Vector3(3,0,3):world.controller.transform.position,dt);if(target&&target.record.partnerHeld&&target.record.partnerClaim==record.id){target.transform.position=transform.position+transform.forward*.35f;target.record.position=target.transform.position;}record.position=transform.position;return;}
            if(!target&&record.rest<=0&&g.Phase==ShiftPhase.Night){target=world.animals.Values.Where(a=>a.record.required&&!a.record.species.StartsWith("C")&&!a.record.dead&&!a.record.contained&&!a.record.terminal&&a.record.drivenUntil<=g.save.job.nightSeconds&&string.IsNullOrEmpty(a.record.partnerClaim)&&Vector3.Distance(transform.position,a.transform.position)<=d.radiusM&&(record.type=="H02"||d.targetSpecies.Contains(a.record.species))&&(!record.lethal||!a.record.deliveryTarget)&&a.transform.position.y<.8f&&world.Route(transform.position,a.transform.position).Count>0).OrderBy(a=>Vector3.Distance(transform.position,a.transform.position)).FirstOrDefault();if(target){record.target=target.record.id;record.chase=8;record.windup=0;if(record.type=="H01")target.record.partnerClaim=record.id;}}
            if(!target){var point=record.command=="Station"||record.command=="Point"?record.commandPoint:world.controller.transform.position;if(Vector3.Distance(transform.position,point)>2)Walk(point,dt);record.position=transform.position;return;}
            if(record.type=="H01"){
                if(target.record.partnerHeld&&target.record.partnerClaim==record.id){record.chase-=dt;target.transform.position=transform.position+transform.forward*.35f;target.record.position=target.transform.position;if(record.chase<=0){target.record.partnerClaim=null;target.record.partnerHeld=false;record.target=null;record.rest=4*g.SkillValue("partnerRestCooldownMultiplier",1);}}
                else{record.chase-=dt;Walk(target.transform.position,dt);if(Vector3.Distance(transform.position,target.transform.position)<.65f&&world.ClearLine(transform.position+Vector3.up*.2f,target.transform.position+Vector3.up*.2f)){record.windup+=dt;if(record.windup>=.4f){if(record.lethal){target.record.controlMethod="Companion";target.Kill();target.record.partnerClaim=null;record.target=null;record.rest=4*g.SkillValue("partnerRestCooldownMultiplier",1);}else{target.record.partnerClaim=record.id;target.record.partnerHeld=true;record.chase=8;}}}else record.windup=0;if(record.chase<=0){target.record.partnerClaim=null;target.record.partnerHeld=false;record.target=null;record.rest=4*g.SkillValue("partnerRestCooldownMultiplier",1);}}
            }else{Walk(target.transform.position,dt);if(Vector3.Distance(transform.position,target.transform.position)<=d.barkRadiusM){record.windup+=dt;if(record.windup>=d.barkWindupSeconds){world.AnimalCue("Dog",transform.position,.7f);target.PartnerDrive(transform.position);record.target=null;record.rest=d.barkCooldownSeconds*g.SkillValue("partnerRestCooldownMultiplier",1);g.Notify(g.L("作业犬吠叫驱赶目标","Work dog barked at the target"));}}}
            record.position=transform.position;
        }
    }
    public partial class DemoAnimal {
        public void PartnerDrive(Vector3 origin){alarm=4;record.drivenUntil=world.game.save.job.nightSeconds+8;pause=0;lure=null;food=-1;var away=(transform.position-origin).normalized;var destination=transform.position+away*8;var j=world.game.save.job;if(j.contractIndex>0&&world.game.config.content.contracts[j.contractIndex].type=="Protect"){var b=world.PlayBounds;var p=transform.position;destination=new[]{new Vector3(b.xMin+2.5f,p.y,p.z),new Vector3(b.xMax-2.5f,p.y,p.z),new Vector3(p.x,p.y,b.yMin+2.5f),new Vector3(p.x,p.y,b.yMax-2.5f)}.OrderBy(v=>Vector3.Distance(v,p)).First();}Repath(world.AdditionalGroundNode(destination));think=1;}
        bool AdvanceDogDrive(float dt){if(record.drivenUntil<=world.game.save.job.nightSeconds)return false;State="Driven flee";pause=0;if(pathIndex<route.Count){var next=route[pathIndex];var delta=next-transform.position;delta.y=0;if(delta.sqrMagnitude>.001f)transform.rotation=Quaternion.LookRotation(delta);if(world.ClearLine(transform.position+Vector3.up*.46f,next+Vector3.up*.46f))transform.position=Vector3.MoveTowards(transform.position,next,4*dt);else record.drivenUntil=0;if(Vector3.Distance(transform.position,next)<.08f)pathIndex++;}record.position=transform.position;return true;}
    }
}
